// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor1, address actor2) public {
        vm.assume(amount > 0);
        vm.assume(actor1 != address(0) && actor2 != address(0) && actor1 != address(c) && actor2 != address(c));
        vm.assume(actor1 != actor2);
        vm.assume(uint160(actor1) > 10 && uint160(actor2) > 10);

        vm.deal(actor1, amount);
        vm.prank(actor1);
        c.Put{value: amount}(0);

        // Rule: after a completed Put, the lock is released, so any other
        // admissible Put call must also succeed.
        vm.deal(actor2, amount);
        vm.prank(actor2);
        bool ok = true;
        try c.Put{value: amount}(0) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok && c.Acc(actor2).balance == amount);
    }
}

