pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor, uint256 warp) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 1 ether, 100 ether);
        warp = bound(warp, 1, 1000 days);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0);

        // withdraw becomes possible strictly after unlock time
        vm.warp(block.timestamp + warp + 1);

        bool ok;
        vm.prank(actor);
        try c.Collect(amount) { ok = true; } catch { ok = false; }

        assertTrue(ok && address(c).balance == 0);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 unlockTime, address actor, uint256 amount) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 1 ether, 1000 ether); // deposit at least MinSum so Collect is admissible
        vm.deal(actor, amount);

        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        // unlock time must be in the past for Collect
        if (unlockTime > block.timestamp) vm.warp(unlockTime + 1);
        else vm.warp(block.timestamp + 1);

        // the lock from Put must have been released: collecting the full balance must succeed
        bool ok;
        vm.prank(actor);
        try c.Collect(amount) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint _unlockTime, uint _v1, uint _v2) public {
        require(_v2 <= _v1);
        require(address(this).balance >= _v1 + _v2);
        c.Put{value: _v1}(_unlockTime);
        c.Put{value: _v2}(_unlockTime);
        (, uint bal) = c.Acc(address(this));
        assert(bal == _v1 + _v2);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint _am, uint _dep) public {
        require(_dep >= 1 ether);
        require(_am >= 1 ether);
        require(_am <= _dep);
        require(address(this).balance >= _dep);

        c.Put{value: _dep}(0);
        (uint t, uint b1) = c.Acc(address(this));
        require(b1 == _dep);
        require(block.timestamp > t);

        c.Collect(_am);

        (, uint b2) = c.Acc(address(this));
        assert(b2 == _dep - _am);
    }

    receive() external payable {}
}
